using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ReinforcedEffect", menuName = "Data/Battle/Effects/Enemy/Reinforced Effect")]
public class ReinforcedEffect : Effect
{
	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = "";
		if (amount == EffectsValues.NO_VALUE)
		{
			return GetEffectDescriptionWithAmountReplacedWithX(GetLocalizedDescription(), base.localizationManager.GetLocalizedThenDecreaseEffect(this, 1), GetNumberToReplaceWithX());
		}
		return Smart.Format(GetLocalizedDescription(), base.localizationManager.GetLocalizedThenDecreaseEffect(this, 1), amount);
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		RemoveEffect(0, effectOwner);
		return 0;
	}
}
